questionvariables.text:
/* Randomising measurements */
rad:rand_with_step(21,29,1)/10;
height:rand_with_prohib(101,149,[110,120,130,140])/10;

/* Solutions */

V_C:(1/3)*%pi*rad^2*height;
V_HS:(2/3)*%pi*rad^3;
V_T:V_C+V_HS;

A_C:%pi*rad*sqrt(rad^2+height^2);
A_HS:2*%pi*rad^2;
A_T:A_C+A_HS;

feedbackvariables.text:
/* Node 1: Correct answers */
node1_test: if ans1=decimalplaces(V_C,3) and ans2=decimalplaces(V_HS,3) and (ans3=decimalplaces(V_T,3) or ans3=decimalplaces(V_C,3)+decimalplaces(V_HS,3)) then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Correct volume for cone (2) */
/* Node 4: Correct volume for cone, incorrectly rounded (1) */
node4_test: if abs(ans1-V_C) <= 0.01 then 1 else 0;

/* Node 5: Correct volume for hemisphere (2) */
/* Node 6: Correct volume for hemisphere, incorrectly rounded (1) */
node6_test: if abs(ans2-V_HS) <= 0.01 then 1 else 0;

/* Node 7: Gives volume of full sphere (1) */
node7_test: if abs(ans2-2*V_HS) <= 0.01 then 1 else 0;

/* Node 8: Correct total volume (1) */
node8_test: if ans3=decimalplaces(V_T,3) or ans3=decimalplaces(V_C,3)+decimalplaces(V_HS,3) then 1 else 0;

/* Node 9: Correctly summed volumes (1) */
node9_test: if ans3=decimalplaces(ans1+ans2,3) or ans3=decimalplaces(ans1,3)+decimalplaces(ans2,3) then 1 else 0;

/* Node 1: Correct answers */
node1_test: if ans4=decimalplaces(A_C,3) and ans5=decimalplaces(A_HS,3) and ans6=decimalplaces(A_T,3) then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Correct area for cone (2) */
/* Node 4: Correct area or cone, incorrectly rounded (1) */
node4_test: if abs(ans4-A_C) <= 0.01 then 1 else 0;

/* Node 5: Correct area for cone, but including circular base (1) */
node5_test: if abs(ans4-A_C-%pi*rad^2) <= 0.01 then 1 else 0;

/* Node 6: Correct area for hemisphere (2) */
/* Node 7: Correct area for hemisphere, incorrectly rounded (1) */
node7_test: if abs(ans5-A_HS) <= 0.01 then 1 else 0;

/* Node 8: Correct area for hemisphere, but including circular base (1) */
node8_test: if abs(ans5-A_HS-%pi*rad^2) <= 0.01 then 1 else 0;

/* Node 9: Gives area of full sphere (1) */
node9_test: if abs(ans5-2*A_HS) <= 0.01 then 1 else 0;

/* Node 10: Correct total areas (1) */
node10_test: if ans6=decimalplaces(A_T,3) or ans3=decimalplaces(A_C,3)+decimalplaces(A_HS,3) then 1 else 0;

/* Node 11: Correctly summed areas (1) */
node11_test: if ans6=decimalplaces(ans4+ans5,3) or ans6=decimalplaces(ans4,3)+decimalplaces(ans5,3) then 1 else 0;
